// src/router/protected/ProtectedRouter.jsx
import { useSelector } from "react-redux";
import { Navigate } from "react-router-dom";
import { IS_DEMO } from "../../api/demoConfig";

const ProtectedRouter = ({ children }) => {
  const isLogin = useSelector((s) => s.login.isLogin);

  // 데모면 보호 라우팅 끔
  if (IS_DEMO) return children;

  // 데모가 아니면 로그인 체크
  if (!isLogin) return <Navigate replace to="/login" />;

  return children;
};

export default ProtectedRouter;
